// GetSetPower returns the "set power" value if any effect sets it, or nil
// Later effects override earlier ones (by timestamp)
func (m *EffectManager) GetSetPower(card *Card, sourceControllerIdx int) *int {
	m.mu.RLock()
	defer m.mu.RUnlock()

	var result *int
	var latestTimestamp int64

	for _, e := range m.effects {
		if e.SetPower != nil && m.effectAffectsCard(e, card, sourceControllerIdx) {
			if result == nil || e.Timestamp > latestTimestamp {
				result = e.SetPower
				latestTimestamp = e.Timestamp
			}
		}
	}
	return result
}
