// HasSwitchPT reports whether an active switch_pt (Layer 7e,
// ticket:engine.switch-pt/v1) effect applies to card. Presence-only (no
// stacking order), matching the bounded self/target/each scopes this
// primitive supports.
func (m *EffectManager) HasSwitchPT(card *Card, sourceControllerIdx int) bool {
	m.mu.RLock()
	defer m.mu.RUnlock()

	for _, e := range m.effects {
		if e.SwitchPowerToughness && m.effectAffectsCard(e, card, sourceControllerIdx) {
			return true
		}
	}
	return false
}
