<<<NEWFILE backend/game/switch_pt_test.go
package game

import "testing"

// TestSwitchPT_TargetCreatureAndCleanup proves the switch_pt primitive
// (ticket:engine.switch-pt/v1): a targeted switch_pt effect turns 2/5 into
// 5/2 without touching printed base P/T, an unaffected creature is left
// alone, and the existing end-of-turn cleanup path restores 2/5.
func TestSwitchPT_TargetCreatureAndCleanup(t *testing.T) {
	gs := NewGame("P0", "P1", false)

	target := NewCreature("Switch PT Target", ManaCost{}, 2, 5, 1)
	target.Owner, target.Controller = 0, 0
	gs.Battlefield.AddCard(target)

	bystander := NewCreature("Switch PT Bystander", ManaCost{}, 3, 3, 1)
	bystander.Owner, bystander.Controller = 1, 1
	gs.Battlefield.AddCard(bystander)

	source := NewCreature("Switch PT Source", ManaCost{}, 1, 1, 1)
	source.Owner, source.Controller = 0, 0
	gs.Battlefield.AddCard(source)

	gs.EffectManager.Register(&ContinuousEffect{
		Source:               source,
		AffectsSpecific:      target.ID,
		SwitchPowerToughness: true,
		UntilEOT:             true,
	})

	if p, tg := target.GetPowerWithEffects(gs.EffectManager), target.GetToughnessWithEffects(gs.EffectManager); p != 5 || tg != 2 {
		t.Fatalf("target after switch_pt = %d/%d, want 5/2", p, tg)
	}

	if p, tg := bystander.GetPowerWithEffects(gs.EffectManager), bystander.GetToughnessWithEffects(gs.EffectManager); p != 3 || tg != 3 {
		t.Fatalf("unaffected bystander = %d/%d, want unchanged 3/3", p, tg)
	}

	gs.EffectManager.RemoveUntilEOT()

	if p, tg := target.GetPowerWithEffects(gs.EffectManager), target.GetToughnessWithEffects(gs.EffectManager); p != 2 || tg != 5 {
		t.Fatalf("target after cleanup = %d/%d, want restored 2/5", p, tg)
	}

	if base := *target.BasePower; base != 2 {
		t.Fatalf("printed BasePower mutated: got %d, want 2", base)
	}
	if base := *target.BaseToughness; base != 5 {
		t.Fatalf("printed BaseToughness mutated: got %d, want 5", base)
	}
}
>>>END

EXPECT: A switch_pt ContinuousEffect (Layer 7e) now swaps a creature's current power/toughness — composed through existing 7b/7c modifiers, base values untouched — for self/target/each-creature scopes dispatched via the ability-effect switch, expires through the existing RemoveUntilEOT cleanup, and is proven by TestSwitchPT_TargetCreatureAndCleanup (2/5→5/2, bystander unchanged, cleanup restores 2/5).
